 const executable=join(destination,'bun-windows-x64/bun.exe');if(!existsSync(executable))throw Error('Missing pinned runtime');
 const passes=Number(process.argv[2]??'1');if(!Number.isInteger(passes)||passes<1||passes>5)throw Error('Invalid bounded repeat count');
