  const output=new TextDecoder().decode(run.stdout)+new TextDecoder().decode(run.stderr);
  runs.push({command,exit:run.exitCode,output});
  writeFileSync('.git/b11-schema-old-runtime.json',JSON.stringify({recordedAt:new Date().toISOString(),url,digest,bytes:bytes.length,runs,sourceInputs:sourcePaths.map(path=>({path,sourceHash:sourceHash(readFileSync(path,'utf8'))})),source:readFileSync('.git/b11-schema-old-runtime.ts','utf8')},null,2)+'\n');
  console.log(JSON.stringify({group,exit:run.exitCode,summary:output.slice(-200)}));
