import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
const group=JSON.parse(readFileSync('.git/b11-schema-group.json','utf8')) as string[];
const inputs=discoverInventory(process.cwd()).files.filter(f=>f.path==='src/infrastructure/database/schema.ts'||group.some(p=>p.endsWith('.ts')?p===f.path:f.path.startsWith(p+'/'))).map(f=>({path:f.path,sourceHash:f.sourceHash}));
const storage=createOwnedTestDirectory('memory-schema-compat-');
try{
 const command=[process.execPath,'test','--timeout','15000',...group];
