import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-schema-diagnostic-');
const repositories=["src/infrastructure/database/schema.ts"];
const driver="tests/infrastructure/database/schema-lifecycle.test.ts",paths=["src/infrastructure/database/schema.ts","tests/infrastructure/database/schema-lifecycle.test.ts","tests/infrastructure/database/services/search-context-lifecycle.test.ts","tests/infrastructure/database/repositories/core-lifecycle.test.ts","tests/infrastructure/database/repositories/embedding-repository-lifecycle.test.ts","tests/infrastructure/database/repositories/friction-lifecycle.test.ts","tests/infrastructure/database/repositories/graph-persona-lifecycle.test.ts","tests/infrastructure/database/repositories/ingestion-lifecycle.test.ts","tests/infrastructure/database/repositories/knowledge-repository-lifecycle.test.ts","tests/infrastructure/database/repositories/memory-state-lifecycle.test.ts","tests/infrastructure/database/repositories/record-repository-lifecycle.test.ts"];
const tests=["tests/infrastructure/database/schema-lifecycle.test.ts","src/infrastructure/database/schema.test.ts","tests/infrastructure/database/services/search-context-lifecycle.test.ts","tests/infrastructure/database/repositories/core-lifecycle.test.ts","tests/infrastructure/database/repositories/embedding-repository-lifecycle.test.ts","tests/infrastructure/database/repositories/friction-lifecycle.test.ts","tests/infrastructure/database/repositories/graph-persona-lifecycle.test.ts","tests/infrastructure/database/repositories/ingestion-lifecycle.test.ts","tests/infrastructure/database/repositories/knowledge-repository-lifecycle.test.ts","tests/infrastructure/database/repositories/memory-state-lifecycle.test.ts","tests/infrastructure/database/repositories/record-repository-lifecycle.test.ts"];
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content);}
const runs:any[]=[];
try{
 for(const path of tests.slice(1))put(path,readFileSync(path,'utf8').replace('"sqlite-vec"',JSON.stringify(Bun.resolveSync('sqlite-vec',root).replaceAll('\\','/'))));
 for(const path of [...tests,...paths])for(const match of readFileSync(path,'utf8').matchAll(/from ["'](\.[^"']+)["']/g)){
 const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts');const local=target.slice(root.length+1).replaceAll('\\','/');
 if(!paths.includes(local)&&!tests.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
}
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 const mutations=[
 ['no-upgrade-transaction','db.transaction(() => {','(() => {'],
 ['stale-cleared-summary','AFTER UPDATE OF summary ON sessions\nBEGIN',"AFTER UPDATE OF summary ON sessions\nWHEN new.summary IS NOT NULL AND new.summary != ''\nBEGIN"],
 ['missing-insert-index','AFTER INSERT ON sessions\nWHEN new.summary IS NOT NULL','AFTER INSERT ON sessions\nWHEN 0 AND new.summary IS NOT NULL'],
 ['no-index-reconciliation','SELECT id, summary FROM sessions WHERE summary IS NOT NULL','SELECT id, summary FROM sessions WHERE 0 AND summary IS NOT NULL'],
 ['always-rebuild','if (marker.get()) return;','marker.get();'],
 ['missing-delete-index','AFTER DELETE ON sessions BEGIN','AFTER DELETE ON sessions WHEN 0 BEGIN'],
];
const faults=mode==='faults'?[
 ...mutations.map(([kind,from,to])=>({path:repositories[0],kind,from,to})),
  ...repositories.flatMap(path=>[...originals.get(path)!.matchAll(/using \w+ =/g)].map((match,index)=>({path,index,offset:match.index,kind:'missing-disposal'}))),

 ]:[];
 for(const fault of [null,...faults]){
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){const content=originals.get(fault.path)!;if('from' in fault){if(!content.includes(fault.from))throw Error('Missing mutation '+fault.kind);put(fault.path,content.replace(fault.from,fault.to));}else put(fault.path,content.slice(0,fault.offset)+'const'+content.slice(fault.offset+5));}
  const command=[process.execPath,'test','--timeout','15000',...(mode==='measure'?tests:[driver])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:45000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);
  runs.push({fault,command,exit:child.exitCode,output});
  if(fault?child.exitCode===0||!output.includes('(fail)'):child.exitCode!==0)throw Error('Unexpected result\n'+output);
 }
 let measurement:unknown;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  const files=paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return{path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};});
  measurement={files,rawCoverage:raw};console.log(JSON.stringify(files));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault,exit:run.exit}))));
